
begin;

truncate table
    public.workflow_task_assignees,
    public.workflow_notifications,
    public.workflow_history,
    public.workflow_tasks,
    public.workflow_instances,
    public.document_history,
    public.document_revisions,
    public.documents,
    public.document_counters
restart identity;

do $$
declare r record;
begin
    for r in
        select p.oid::regprocedure as signature
        from pg_proc p
        join pg_namespace n on n.oid=p.pronamespace
        where n.nspname='public' and p.prokind='f'
          and p.proname in (
            'approve_sop_revision','create_new_sop','create_sop_revision',
            'delete_sop_draft','discard_sop_revision','reject_sop_revision',
            'submit_sop_for_validation','supervisor_release_sop_revision',
            'sync_document_history_to_sop_history','sync_document_revision_to_sop_revision',
            'sync_document_to_sop_document','sync_sop_history_to_document_history',
            'sync_sop_revision_to_document_revisions','sync_sop_document_to_documents',
            'update_sop_draft','user_participated_in_revision','validate_sop_revision'
          )
    loop
        execute 'drop function if exists ' || r.signature || ' cascade';
    end loop;
end;
$$;

drop table if exists public.sop_workflow_history cascade;
drop table if exists public.sop_revisions cascade;
drop table if exists public.sop_documents cascade;
drop table if exists public.sop_counters_legacy cascade;


select pg_catalog.setval(pg_get_serial_sequence('public.documents','id'),457,true);

commit;
